command:
ssh -o BatchMode=yes -o ConnectTimeout=10 mai-tai-vps 'sudo -n nice -n 19 env PYTHONDONTWRITEBYTECODE=1 /home/trader/project-mai-tai/.venv/bin/python -' <<'PY'
import json,subprocess
from datetime import datetime,timezone
from project_mai_tai.settings import Settings
unit='project-mai-tai-oms.service'; pid=int(subprocess.check_output(['systemctl','show','--property=MainPID','--value',unit],text=True).strip())
keys=['oms_broker_sync_interval_seconds','oms_native_oco_exit_poll_enabled','oms_native_oco_exit_poll_min_secs','webull_positions_throttle_secs','webull_positions_backoff_base_secs','webull_positions_backoff_max_secs']; allowed={'MAI_TAI_'+k.upper():k for k in keys}
with open(f'/proc/{pid}/environ','rb') as f: raw=f.read(128*1024+1)
if len(raw)>128*1024: raise RuntimeError('128KiB environ bound')
values={}
for field in raw.split(b'\0'):
 k,sep,v=field.partition(b'='); key=k.decode(errors='replace')
 if key in allowed: values[allowed[key]]=v.decode(errors='replace')
s=Settings(_env_file='/etc/project-mai-tai/project-mai-tai.env',**values)
print(json.dumps({'kind':'OWN_WEBULL429_LIVE_PROCESS_ALLOWLIST','captured_at_utc':datetime.now(timezone.utc).isoformat(),'unit':unit,'main_pid':pid,'process_environment_allowlist':values,'resolved_with_process_overrides':{k:getattr(s,k) for k in keys},'limitation':'Does not introspect in-memory mutated Settings; missing process keys resolved against current env file.'},indent=2))
PY

